// Some portions generated by Claude
/**
 * "Organize network". Every connected component is split into its 2-core and the pendant trees hanging off it
 * (`graph-layout-structure.ts`). A card with at least `FAN_MIN` pendant children gets a fan: those children, each with
 * everything hanging below it, are drawn on a box-shaped ring around the card (`graph-layout-fans.ts`). All other
 * cards (the core and the pendant cards of cards with few children) are laid out by stress (`graph-layout-stress.ts`),
 * a fanned card counting as big as its fan so the fan gets its room. Fans are then placed on the side away from the
 * card's other links and clear of them, and a short stress polish with each fan's actual extent closes what the
 * estimate left open.
 *
 * A shared hub (a card whose removal splits the core into several parts, like an award shared by groups of
 * researchers) collapses every graph distance through itself, so stress cannot separate the parts. Such a hub is drawn
 * like a fan anchor whose units are the parts: each part is laid out beside the hub, then the parts are arranged on
 * the hub's ring. Components are packed as polyominoes (`graph-layout-packing.ts`).
 */
import {graphNodeSize} from './graph-geometry.ts';
import {withCollapsedClassLinks} from './graph-class-links.ts';
import {decomposeComponent, componentsOf, type Decomposition} from './graph-layout-structure.ts';
import {placeFan, unitShapes, type Extents, type Fan, type FanObstacles, type FanSpacing, type Side, type UnitShape} from './graph-layout-fans.ts';
import {drawingCost, segmentHitsBox, stressLayout, untangle, type StressProblem} from './graph-layout-stress.ts';
import {packComponents} from './graph-layout-packing.ts';
import {separateLayoutRectangles} from './graph-layout-overlap.ts';
import {layoutNodeFixed} from './graph-layout-topology.ts';
import {LAYOUT_SPACING as gap} from './graph-layout-spacing.ts';
import type {Graph, PointerPosition} from './graph-types.ts';
import type {LayoutOptions, LayoutResult} from './graph-layout-engine.ts';

/** Visible length of an arrow between two cards. */
export const ARROW_LENGTH = 90;
/** A card with at least this many pendant children fans them; fewer stay in the stress layout. */
export const FAN_MIN = 4;
/** Part of the ring a fan uses when its anchor has links into the rest of the drawing. */
const FAN_OPEN_SPAN = 0.75;
/** Cores up to this many cards (and this many with their fans) are laid out from several starts. */
const MULTI_START_LIMIT = 250;
const MULTI_START_CARDS = 400;
/** Groups up to this many cards get the local search against crossings and cuts. */
const UNTANGLE_LIMIT = 350;
/** The last local search, which moves fans with their anchors, runs on drawings up to this many cards. */
const BODY_UNTANGLE_LIMIT = 260;
/** A shared hub links at least this many core cards and splits the core into at least `HUB_PARTS` parts. */
const HUB_MIN_DEGREE = 8;
const HUB_PARTS = 3;

type Prepared = {
  graph: Graph;
  width: Float64Array;
  height: Float64Array;
  neighbors: number[][];
  /** Every card each card links to, collapsed class links included (they place a class card among its instances). */
  linked: number[][];
  fixed: Uint8Array;
  /** Drawing order key of a card under its parent: predicate of the link, kind, type, label. */
  order: (parent: number, child: number) => string;
};

function prepare(graph: Graph, options: LayoutOptions): Prepared {
  const index = new Map(graph.nodes.map((node, i) => [node.id, i]));
  const n = graph.nodes.length;
  const width = new Float64Array(n), height = new Float64Array(n);
  graph.nodes.forEach((node, i) => {
    const size = options.nodeSizes?.get(node.id) ?? graphNodeSize(node);
    width[i] = size.width; height[i] = size.height;
  });
  // Links to classes with many instances are collapsed on the canvas: they neither shape nor draw.
  const {graph: shaping} = withCollapsedClassLinks(graph);
  const sets = graph.nodes.map(() => new Set<number>());
  const predicate = new Map<number, string>();
  for (const edge of shaping.edges) {
    const a = index.get(edge.source), b = index.get(edge.target);
    if (a === undefined || b === undefined || a === b) continue;
    sets[a].add(b); sets[b].add(a);
    const key = a < b ? a * n + b : b * n + a;
    if (!predicate.has(key)) predicate.set(key, edge.label || edge.predicate);
  }
  const neighbors = sets.map(set => [...set].sort((x, y) => x - y));
  const all = graph.nodes.map(() => new Set<number>());
  for (const edge of graph.edges) {
    const a = index.get(edge.source), b = index.get(edge.target);
    if (a !== undefined && b !== undefined && a !== b) { all[a].add(b); all[b].add(a); }
  }
  const linked = all.map(set => [...set].sort((x, y) => x - y));
  const fixed = Uint8Array.from(graph.nodes, node => (layoutNodeFixed(node, options) ? 1 : 0));
  const order = (parent: number, child: number) => {
    const node = graph.nodes[child];
    const key = parent < child ? parent * n + child : child * n + parent;
    return [predicate.get(key) ?? '', node.kind === 'literal' ? '1' : '0', node.types?.[0]?.label ?? '', node.label, node.id].join('\u0000');
  };
  return {graph, width, height, neighbors, linked, fixed, order};
}

type Point = {x: number; y: number};
type Layout = Map<number, Point>;

const cardExtents = (p: Prepared, card: number): Extents =>
  ({left: p.width[card] / 2, right: p.width[card] / 2, top: p.height[card] / 2, bottom: p.height[card] / 2});

/** The card boxes of a fan as offsets from its anchor's centre. */
function fanBoxes(p: Prepared, fan: Fan) {
  const boxes: Array<{minX: number; maxX: number; minY: number; maxY: number}> = [];
  // A ring's inside carries its arrows: other cards keep out of it.
  if (fan.ring) boxes.push({minX: -fan.inner.hx, maxX: fan.inner.hx, minY: -fan.inner.hy, maxY: fan.inner.hy});
  for (const unit of fan.placements) for (const [card, o] of unit.shape.offsets) {
    if (card < 0) continue;
    const x = unit.x + o.x, y = unit.y + o.y;
    boxes.push({minX: x - p.width[card] / 2, maxX: x + p.width[card] / 2, minY: y - p.height[card] / 2, maxY: y + p.height[card] / 2});
  }
  return boxes;
}

/** Adds the cards of a fan around its anchor at (ax, ay) to `layout`. */
function writeFan(layout: Layout, fan: Fan, ax: number, ay: number) {
  for (const unit of fan.placements) for (const [card, o] of unit.shape.offsets) {
    if (card < 0) continue;
    layout.set(card, {x: ax + unit.x + o.x, y: ay + unit.y + o.y});
  }
}

/**
 * Link lengths in hops that spread the neighbourhood of a hub: a link whose two cards share few neighbours out of many
 * (a hub to one of its many neighbours) is longer, like the symmetric-difference link lengths of cola.js.
 */
export function hubLinkLengths(n: number, links: readonly number[]) {
  const sets = Array.from({length: n}, () => new Set<number>());
  for (let l = 0; l < links.length; l += 2) { sets[links[l]].add(links[l + 1]); sets[links[l + 1]].add(links[l]); }
  const lengths = new Float64Array(links.length / 2);
  for (let l = 0; l < links.length; l += 2) {
    const a = links[l], b = links[l + 1];
    let shared = 0;
    for (const k of sets[a]) if (sets[b].has(k)) shared++;
    const difference = sets[a].size + sets[b].size - 2 - 2 * shared;
    lengths[l / 2] = 1 + 0.5 * Math.max(0, Math.log(difference / 6));
  }
  return lengths;
}

/**
 * Springs between cards of the same type that share neighbours (weighted like Adamic–Adar: a shared neighbour with
 * fewer links counts more), so similar resources sit together; a hub shared by many counts little.
 */
function similaritySprings(p: Prepared, group: number[], local: Map<number, number>) {
  const shared = new Map<number, number>();
  const typeOf = (card: number) => p.graph.nodes[card].types?.[0]?.id ?? '';
  for (const v of group) {
    if (!typeOf(v)) continue;
    for (const w of p.neighbors[v].slice(0, 48)) {
      const weight = 1 / Math.log2(1 + p.neighbors[w].length);
      for (const u of p.neighbors[w].slice(0, 48)) {
        if (u <= v || !local.has(u) || typeOf(u) !== typeOf(v)) continue;
        const key = local.get(v)! * group.length + local.get(u)!;
        shared.set(key, (shared.get(key) ?? 0) + weight);
      }
    }
  }
  return [...shared].filter(([, weight]) => weight >= 0.3).sort((a, b) => a[0] - b[0]).map(([key, weight]) => {
    const a = Math.floor(key / group.length), b = key % group.length;
    const length = (p.width[group[a]] + p.width[group[b]] + p.height[group[a]] + p.height[group[b]]) / 4 + ARROW_LENGTH / 2;
    return {a, b, length, weight: 0.5 * weight};
  });
}

type Context = {p: Prepared; d: Decomposition; shape: (card: number, side: Side) => UnitShape; fanned: Set<number>;
  options: LayoutOptions; spacing: FanSpacing;
  /** Extending or tidying a drawing: how strongly each card stays where it is (absent: organize from scratch). */
  keep?: (card: number) => number;
  /** Cards whose current position counts (placed before this layout). */
  placed?: (card: number) => boolean;
  /**
   * Extending a drawing: the children each card would have if no card were held in the core, so a fanned card's ring
   * members include those that may not move.
   */
  ring?: number[][]};

/** A fanned card's room in a stress layout: its fan packed on one side, as a box centred on the card. */
function fanFootprint(c: Context, card: number): Extents {
  const {p, d, shape, spacing} = c;
  const e = placeFan({halfWidth: p.width[card] / 2, halfHeight: p.height[card] / 2, units: d.children[card], shape, spacing, facing: 0, span: 1}).extents;
  const halfWidth = Math.max(p.width[card] / 2, (e.left + e.right) / 2), halfHeight = Math.max(p.height[card] / 2, (e.top + e.bottom) / 2);
  return {left: halfWidth, right: halfWidth, top: halfHeight, bottom: halfHeight};
}

/**
 * Stress layout of `cards` (with their fans) around (0, 0). With `hub`, the hub card is fixed at (0, 0) and the other
 * cards are kept in the half plane on the `axis` side of it (right of it for x, below it for y); the hub is not in the
 * result.
 */
function layoutGroup(c: Context, cards: number[], hub?: {card: number; axis: 'x' | 'y'}): Layout {
  const {p, d, shape, fanned, options, spacing} = c;
  const group = hub ? [...cards, hub.card] : cards;
  const m = group.length, local = new Map(group.map((card, i) => [card, i]));
  const result: Layout = new Map();
  if (cards.length === 1 && !hub) {
    const root = cards[0], node = p.graph.nodes[root];
    // Extending a drawing, a placed root stays where it is.
    const stays = (p.fixed[root] || c.placed?.(root)) && node.x !== undefined && node.y !== undefined;
    const at = stays ? {x: node.x!, y: node.y!} : {x: 0, y: 0};
    result.set(root, at);
    if (held(c, root)) holdFan(c, root, at, result, drawnOf(p, [root], () => at, []));
    else if (fanned.has(root)) {
      writeFan(result, placeFan({halfWidth: p.width[root] / 2, halfHeight: p.height[root] / 2, units: d.children[root], shape, spacing, spread: true}), at.x, at.y);
    }
    return result;
  }
  const links: number[] = [];
  for (const card of group) for (const k of p.neighbors[card]) {
    const j = local.get(k);
    if (j !== undefined && card < k) links.push(local.get(card)!, j);
  }
  const linkLengths = hubLinkLengths(m, links);
  const springs = c.keep || m > MULTI_START_LIMIT ? [] : similaritySprings(p, group, local);
  const refans = (card: number) => fanned.has(card) && card !== hub?.card && !held(c, card);
  const estimate = group.map(card => (refans(card) ? fanFootprint(c, card) : cardExtents(p, card)));
  const start = c.keep ? startPositions(c, group) : null;
  const problem: StressProblem = {
    left: Float64Array.from(estimate, e => e.left), right: Float64Array.from(estimate, e => e.right),
    top: Float64Array.from(estimate, e => e.top), bottom: Float64Array.from(estimate, e => e.bottom),
    x: Float64Array.from(group, (card, i) => (start ? start[i].x : hub ? 0 : p.graph.nodes[card].x ?? 0)),
    y: Float64Array.from(group, (card, i) => (start ? start[i].y : hub ? 0 : p.graph.nodes[card].y ?? 0)),
    links: Int32Array.from(links), linkLengths,
    fixed: Uint8Array.from(group, card => (hub ? (card === hub.card ? 1 : 0) : p.fixed[card] || held(c, card) || grows(c, card) ? 1 : 0)),
  };
  if (hub) {
    // Beside the hub: at least an arrow's length away from its card on the chosen side.
    const h = local.get(hub.card)!;
    if (hub.axis === 'x') problem.minX = Float64Array.from(group, (_, i) => (i === h ? -Infinity : p.width[hub.card] / 2 + ARROW_LENGTH + estimate[i].left));
    else problem.minY = Float64Array.from(group, (_, i) => (i === h ? -Infinity : p.height[hub.card] / 2 + ARROW_LENGTH + estimate[i].top));
  }
  const common = {edgeLength: ARROW_LENGTH, clearX: gap.nodeGapX, clearY: gap.nodeGapY, aspectRatio: options.aspectRatio ?? 1.6};
  if (c.keep) {
    // Extending or tidying: start where the cards are, stay near the placed ones, and only take the later, smaller steps.
    // The cards of a held fan stay too: the others keep clear of them.
    stressLayout({...problem, anchorX: problem.x.slice(), anchorY: problem.y.slice(),
      anchorWeight: Float64Array.from(group, card => (c.placed!(card) ? c.keep!(card) : 0)),
      bodies: group.map(card => (held(c, card) ? heldBody(c, card) : undefined))},
    {...common, initialize: false, epochs: 40, startFraction: 0.5, seed: options.seed ?? 7});
  }
  // Stress has local minima: small groups are drawn from a few starts and the finished drawings compared. Similar cards
  // pulled together are one more start, and so is the drawing turned across the viewport.
  const single = (problem.fixed!.some(Boolean) && !hub) || m > MULTI_START_LIMIT || totalCards(c, group) > MULTI_START_CARDS;
  const aspect = options.aspectRatio ?? 1.6;
  const starts = c.keep ? [] : single ? [{random: false, springs: false, turned: false}]
    : [{random: false, springs: true, turned: false}, {random: false, springs: false, turned: false}, {random: false, springs: false, turned: true},
      {random: true, springs: false, turned: false}, {random: true, springs: true, turned: false}]
      .filter(start => !start.springs || springs.length);
  const finish = (attempt: StressProblem) => {
    if (!c.keep && m <= UNTANGLE_LIMIT) untangle(attempt);
    return drawFans(c, group, local, links, attempt, refans, hub?.card);
  };
  if (c.keep) return finish(problem);
  const drawings = starts.map((begin, k) => {
    const attempt: StressProblem = {...problem, x: problem.x.slice(), y: problem.y.slice(), springs: begin.springs ? springs : undefined};
    stressLayout(attempt, {...common, aspectRatio: begin.turned ? 1 / aspect : aspect, initialize: true, randomStart: begin.random, seed: (options.seed ?? 7) + k * 101});
    return {x: attempt.x, y: attempt.y, conflicts: starts.length > 1 ? drawingCost(attempt) : 0, shape: boxShape(attempt, aspect), similar: begin.springs || !springs.length};
  });
  // Fewest crossings and cuts first; within about one conflict similar cards kept together win, then a more compact
  // box shaped like the viewport. (Comparing the finished drawings instead picks the same starts at three times the cost.)
  const smallest = Math.min(...drawings.map(drawing => drawing.shape));
  let best = drawings[0], bestCost = Infinity;
  for (const drawing of drawings) {
    const cost = drawing.conflicts + (drawing.similar ? 0 : 0.9) + 1.5 * (drawing.shape - smallest);
    if (cost < bestCost) { best = drawing; bestCost = cost; }
  }
  problem.x.set(best.x); problem.y.set(best.y);
  return finish(problem);
}

/** Cards of a group with everything fanned around them. */
function totalCards(c: Context, group: number[]) {
  let total = 0;
  for (const card of group) total += c.fanned.has(card) ? subtree(c, card).length : 1;
  return total;
}

/**
 * Places the fans of a stress drawing, polishes it with each fan as a rigid body, and returns every card's position
 * (the hub's excepted).
 */
function drawFans(c: Context, group: number[], local: Map<number, number>, links: number[], problem: StressProblem,
  refans: (card: number) => boolean, hub: number | undefined): Layout {
  const {p, d, shape, options, spacing} = c;
  const m = group.length, result: Layout = new Map();
  const common = {edgeLength: ARROW_LENGTH, clearX: gap.nodeGapX, clearY: gap.nodeGapY, aspectRatio: options.aspectRatio ?? 1.6};
  // Held fans first: their anchors stay, so their cards are final and the fans drawn anew keep clear of them.
  const kept: Layout = new Map(), keptBodies = new Map<number, Array<{minX: number; maxX: number; minY: number; maxY: number}>>();
  const holding = group.map((_, i) => i).filter(i => group[i] !== hub && held(c, group[i]));
  if (holding.length) {
    const drawn = drawnOf(p, group, card => ({x: problem.x[local.get(card)!], y: problem.y[local.get(card)!]}), links.map(l => group[l]));
    for (const i of holding) {
      const before = new Set(kept.keys());
      holdFan(c, group[i], {x: problem.x[i], y: problem.y[i]}, kept, drawn);
      keptBodies.set(i, [ringInside(c, group[i]), ...[...kept].filter(([card]) => !before.has(card)).map(([card, at]) => ({minX: at.x - problem.x[i] - p.width[card] / 2,
        maxX: at.x - problem.x[i] + p.width[card] / 2, minY: at.y - problem.y[i] - p.height[card] / 2, maxY: at.y - problem.y[i] + p.height[card] / 2}))]);
    }
  }
  const keptBoxes: Extents[] = [...kept].map(([card, at]) => ({left: at.x - p.width[card] / 2, right: at.x + p.width[card] / 2,
    top: at.y - p.height[card] / 2, bottom: at.y + p.height[card] / 2}));
  const fans = new Map<number, Fan>();
  const placeFans = () => {
    fans.clear();
    const order = group.map((_, i) => i).filter(i => refans(group[i]))
      .sort((a, b) => d.children[group[b]].length - d.children[group[a]].length || a - b);
    const placedUnits: Extents[] = [...keptBoxes];
    for (const i of order) {
      const card = group[i], ax = problem.x[i], ay = problem.y[i];
      const obstacles: FanObstacles = {boxes: [], segments: []};
      for (let j = 0; j < m; j++) {
        if (j === i) continue;
        const other = group[j];
        obstacles.boxes.push({left: problem.x[j] - p.width[other] / 2 - ax, right: problem.x[j] + p.width[other] / 2 - ax,
          top: problem.y[j] - p.height[other] / 2 - ay, bottom: problem.y[j] + p.height[other] / 2 - ay});
      }
      for (let l = 0; l < links.length; l += 2) {
        const a = links[l], b = links[l + 1];
        obstacles.segments.push([problem.x[a] - ax, problem.y[a] - ay, problem.x[b] - ax, problem.y[b] - ay]);
      }
      for (const box of placedUnits) obstacles.boxes.push({left: box.left - ax, right: box.right - ax, top: box.top - ay, bottom: box.bottom - ay});
      // Face away from the card's links in the stress layout, and keep clear of their directions.
      let vx = 0, vy = 0;
      obstacles.directions = [];
      for (const k of p.neighbors[card]) {
        const j = local.get(k);
        if (j === undefined) continue;
        const dx = problem.x[j] - ax, dy = problem.y[j] - ay, length = Math.hypot(dx, dy) || 1;
        vx -= dx / length; vy -= dy / length;
        obstacles.directions.push(Math.atan2(dy, dx));
      }
      const facing: Side = Math.abs(vx) >= Math.abs(vy) ? (vx >= 0 ? 0 : 2) : (vy >= 0 ? 1 : 3);
      // A card linked into the rest of the drawing leaves the quarter of its ring that faces those links open (a C),
      // so its neighbours sit in the gap instead of behind its fan.
      const span = obstacles.directions.length ? FAN_OPEN_SPAN : 1;
      const fan = placeFan({halfWidth: p.width[card] / 2, halfHeight: p.height[card] / 2, units: d.children[card], shape,
        spacing, facing, span, obstacles, direction: Math.hypot(vx, vy) > 1e-6 ? Math.atan2(vy, vx) : undefined});
      fans.set(i, fan);
      for (const unit of fan.placements) {
        placedUnits.push({left: ax + unit.x - unit.shape.extents.left, right: ax + unit.x + unit.shape.extents.right,
          top: ay + unit.y - unit.shape.extents.top, bottom: ay + unit.y + unit.shape.extents.bottom});
      }
    }
  };
  if (group.some(refans)) {
    placeFans();
    // Polish with each fan as a rigid body of card boxes moving with its anchor, starting late in the schedule so the
    // drawing keeps its shape: cards give way to the fans' cards, not to their bounding boxes.
    group.forEach((card, i) => {
      const e = cardExtents(p, card);
      problem.left[i] = e.left; problem.right[i] = e.right; problem.top[i] = e.top; problem.bottom[i] = e.bottom;
    });
    const bodies = () => group.map((_, i) => { const fan = fans.get(i); return fan ? fanBoxes(p, fan) : keptBodies.get(i); });
    stressLayout({...problem, bodies: bodies(), anchorX: problem.x.slice(), anchorY: problem.y.slice(), anchorWeight: new Float64Array(m).fill(0.05)},
      {...common, initialize: false, epochs: 30, startFraction: 0.45, seed: (options.seed ?? 7) + 1});
    // The polish can bring back crossings the local search removed.
    if (!c.keep && m <= UNTANGLE_LIMIT) untangle(problem);
    placeFans();
    // Once more with the final fans moving with their anchors, where the drawing is small enough to search.
    const withBodies = {...problem, bodies: bodies()};
    if (!c.keep && withBodies.bodies.reduce((sum, list) => sum + 1 + (list?.length ?? 0), 0) <= BODY_UNTANGLE_LIMIT) untangle(withBodies);
    // Settle: only the hinges, the final fans moving with their anchors.
    stressLayout(withBodies, {...common, initialize: false, epochs: 2, startFraction: 0.99, seed: (options.seed ?? 7) + 2});
  }
  group.forEach((card, i) => {
    if (card === hub) return;
    result.set(card, {x: problem.x[i], y: problem.y[i]});
    const fan = fans.get(i);
    if (fan) writeFan(result, fan, problem.x[i], problem.y[i]);
  });
  for (const [card, at] of kept) result.set(card, at);
  return result;
}

/** A card and everything hanging below it. */
function subtree(c: Context, card: number) {
  const cards = [card];
  for (let read = 0; read < cards.length; read++) cards.push(...c.d.children[cards[read]]);
  return cards;
}

/**
 * Extending a drawing, a placed fanned card keeps its place and its fan (`holdFan`) when a card of its ring may not
 * move (moving it would tear it from the cards that stay) or when it has no new children (its fan keeps its shape; only
 * its branches with new cards change).
 */
function held(c: Context, card: number) {
  if (!c.keep || !c.fanned.has(card) || !c.placed!(card)) return false;
  return c.ring![card].some(k => c.p.fixed[k]) || c.d.children[card].every(k => c.placed!(k));
}

/** Extending a drawing, a placed fanned card that gained children (the expanded card) stays: the others make room. */
function grows(c: Context, card: number) {
  return Boolean(c.keep) && c.fanned.has(card) && c.placed!(card) && c.d.children[card].some(k => !c.placed!(k));
}

const here = (p: Prepared, card: number): Point => ({x: p.graph.nodes[card].x ?? 0, y: p.graph.nodes[card].y ?? 0});

/** The placed cards of a held fan and the inside of its ring as boxes around its anchor (where they are now). */
function heldBody(c: Context, card: number) {
  const {p} = c, at = here(p, card);
  return [ringInside(c, card), ...subtree(c, card).filter(k => k !== card && c.placed!(k)).map(k => {
    const x = here(p, k).x - at.x, y = here(p, k).y - at.y;
    return {minX: x - p.width[k] / 2, maxX: x + p.width[k] / 2, minY: y - p.height[k] / 2, maxY: y + p.height[k] / 2};
  })];
}

/**
 * The inside of a held fan's ring around its anchor, which its arrows cross: on each side that has children, up to
 * their inner edges; on a side without, the anchor card's own edge (another card may sit in a gap).
 */
function ringInside(c: Context, card: number) {
  const {p} = c, at = here(p, card);
  const units = (c.ring?.[card] ?? c.d.children[card]).filter(k => c.placed!(k)).map(k => ({k, x: here(p, k).x - at.x, y: here(p, k).y - at.y}));
  let spanX = 1e-6, spanY = 1e-6;
  for (const u of units) { spanX = Math.max(spanX, Math.abs(u.x)); spanY = Math.max(spanY, Math.abs(u.y)); }
  let right = Infinity, left = Infinity, top = Infinity, bottom = Infinity;
  for (const {k, x, y} of units) {
    if (Math.abs(x) / spanX >= Math.abs(y) / spanY) {
      if (x >= 0) right = Math.min(right, x - p.width[k] / 2); else left = Math.min(left, -x - p.width[k] / 2);
    } else if (y >= 0) bottom = Math.min(bottom, y - p.height[k] / 2); else top = Math.min(top, -y - p.height[k] / 2);
  }
  const edge = (inner: number, own: number) => (inner === Infinity ? own : Math.max(own, inner));
  const hw = p.width[card] / 2, hh = p.height[card] / 2;
  return {minX: -edge(left, hw), maxX: edge(right, hw), minY: -edge(top, hh), maxY: edge(bottom, hh)};
}

/**
 * What is drawn so far, in absolute coordinates: where each card is, card boxes (with their cards), links, and areas
 * new cards keep out of (the insides of held rings).
 */
type Drawn = {where: Map<number, Point>; boxes: Array<{card: number; box: Extents}>; segments: Array<[number, number, number, number]>;
  areas: Extents[]};

/** The boxes of `cards` at `at(card)` and the links between the pairs in `links` ([a0, b0, a1, b1, …]). */
function drawnOf(p: Prepared, cards: number[], at: (card: number) => Point, links: number[]): Drawn {
  const drawn: Drawn = {where: new Map(), boxes: [], segments: [], areas: []};
  for (const card of cards) put(p, new Map(), drawn, card, at(card));
  for (let l = 0; l < links.length; l += 2) {
    const a = at(links[l]), b = at(links[l + 1]);
    drawn.segments.push([a.x, a.y, b.x, b.y]);
  }
  return drawn;
}

function put(p: Prepared, layout: Layout, drawn: Drawn, card: number, at: Point) {
  layout.set(card, at);
  drawn.where.set(card, at);
  drawn.boxes.push({card, box: {left: at.x - p.width[card] / 2, right: at.x + p.width[card] / 2, top: at.y - p.height[card] / 2, bottom: at.y + p.height[card] / 2}});
}

/**
 * The fan of a held card at `at` (which does not move), into `layout`. Placed cards stay where they are; new cards are
 * drawn around the placed card they hang from: where a card of the fan gained children, all its children are fanned
 * anew around it, outward from its parent and clear of everything drawn; new children of the held card itself go to
 * free places around it. `drawn` holds everything else and grows with what is placed here.
 */
function holdFan(c: Context, anchor: number, at: Point, layout: Layout, drawn: Drawn) {
  const {p, d} = c;
  const grown: number[] = [], fresh: number[] = [];
  const inside = ringInside(c, anchor);
  drawn.areas.push({left: at.x + inside.minX, right: at.x + inside.maxX, top: at.y + inside.minY, bottom: at.y + inside.maxY});
  for (const child of d.children[anchor]) {
    const cards = subtree(c, child);
    if (cards.some(k => !c.placed!(k))) { (c.placed!(child) ? grown : fresh).push(child); continue; }
    for (const k of cards) put(p, layout, drawn, k, here(p, k));
    for (const k of cards) {
      const from = k === child ? at : layout.get(d.parent[k])!, to = layout.get(k)!;
      drawn.segments.push([from.x, from.y, to.x, to.y]);
    }
  }
  for (const child of grown) {
    const own = here(p, child);
    if (d.children[child].some(k => !c.placed!(k))) fanAround(c, child, own, [at], d.children[child], layout, drawn);
    else holdFan(c, child, own, layout, drawn);
    put(p, layout, drawn, child, own);
    drawn.segments.push([at.x, at.y, own.x, own.y]);
  }
  if (fresh.length) {
    // Away from the anchor's links to the rest of the drawing.
    const away = p.neighbors[anchor].filter(k => d.parent[k] !== anchor && drawn.where.has(k)).map(k => drawn.where.get(k)!);
    fanAround(c, anchor, at, away, fresh, layout, drawn);
  }
}

/**
 * Fans `units` (children of `card`, at `at`) around it clear of everything drawn, facing away from `away` (the cards
 * it links to outside the fan), and records them.
 */
function fanAround(c: Context, card: number, at: Point, away: Point[], units: number[], layout: Layout, drawn: Drawn) {
  const {p, d, shape, spacing} = c;
  const obstacles: FanObstacles = {
    boxes: drawn.boxes.filter(entry => entry.card !== card).map(({box}) => ({left: box.left - at.x, right: box.right - at.x, top: box.top - at.y, bottom: box.bottom - at.y})),
    segments: drawn.segments.map(([x0, y0, x1, y1]) => [x0 - at.x, y0 - at.y, x1 - at.x, y1 - at.y] as [number, number, number, number]),
    directions: away.map(q => Math.atan2(q.y - at.y, q.x - at.x)),
    areas: drawn.areas.map(area => ({left: area.left - at.x, right: area.right - at.x, top: area.top - at.y, bottom: area.bottom - at.y})),
  };
  let vx = 0, vy = 0;
  for (const q of away) { const dx = q.x - at.x, dy = q.y - at.y, length = Math.hypot(dx, dy) || 1; vx -= dx / length; vy -= dy / length; }
  const facing: Side = Math.abs(vx) >= Math.abs(vy) ? (vx >= 0 ? 0 : 2) : (vy >= 0 ? 1 : 3);
  const fan = placeFan({halfWidth: p.width[card] / 2, halfHeight: p.height[card] / 2, units, shape, spacing, facing,
    span: away.length ? FAN_OPEN_SPAN : 1, obstacles, direction: Math.hypot(vx, vy) > 1e-6 ? Math.atan2(vy, vx) : undefined});
  const placed: number[] = [];
  for (const unit of fan.placements) for (const [k, o] of unit.shape.offsets) {
    if (k < 0) continue;
    put(p, layout, drawn, k, {x: at.x + unit.x + o.x, y: at.y + unit.y + o.y});
    placed.push(k);
  }
  for (const k of placed) {
    const from = d.parent[k] === card ? at : layout.get(d.parent[k])!, to = layout.get(k)!;
    drawn.segments.push([from.x, from.y, to.x, to.y]);
  }
}

/**
 * Current positions; a card without one starts at the middle of its placed neighbours (a class card whose links are
 * collapsed: of its placed instances).
 */
function startPositions(c: Context, group: number[]): Point[] {
  const {p} = c;
  const middle = (card: number, neighbors: readonly number[]) => {
    let sx = 0, sy = 0, count = 0;
    for (const k of neighbors) {
      const other = p.graph.nodes[k];
      if (c.placed!(k) && other.x !== undefined && other.y !== undefined) { sx += other.x; sy += other.y; count++; }
    }
    return count ? {x: sx / count + ((card * 37) % 17) - 8, y: sy / count + ((card * 53) % 13) - 6} : null;
  };
  return group.map(card => {
    const node = p.graph.nodes[card];
    if (c.placed!(card) && node.x !== undefined && node.y !== undefined) return {x: node.x, y: node.y};
    return middle(card, p.neighbors[card]) ?? middle(card, p.linked[card]) ?? {x: node.x ?? 0, y: node.y ?? 0};
  });
}

/**
 * How well a drawing's box suits a viewport of this width/height ratio: the log of its area plus a mild penalty for a
 * shape unlike the viewport's (smaller is better). A long chain drawn straight along the viewport's long axis beats the
 * same chain drawn diagonally, whose box is far larger even though it fits the screen at a similar zoom.
 */
function boxShape(problem: StressProblem, aspect: number) {
  const {left, right, top, bottom, x, y} = problem;
  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  for (let i = 0; i < x.length; i++) {
    minX = Math.min(minX, x[i] - left[i]); maxX = Math.max(maxX, x[i] + right[i]);
    minY = Math.min(minY, y[i] - top[i]); maxY = Math.max(maxY, y[i] + bottom[i]);
  }
  const width = Math.max(1, maxX - minX), height = Math.max(1, maxY - minY), skew = Math.log(width / height / aspect);
  return Math.log(width * height) + 0.1 * skew * skew;
}

/** Connected parts of `cards` once `hub` is removed. */
function partsWithout(p: Prepared, cards: number[], hub: number) {
  const inside = new Set(cards), seen = new Set<number>([hub]), parts: number[][] = [];
  for (const seed of cards) {
    if (seen.has(seed)) continue;
    const part = [seed];
    seen.add(seed);
    for (let read = 0; read < part.length; read++) for (const k of p.neighbors[part[read]]) {
      if (inside.has(k) && !seen.has(k)) { seen.add(k); part.push(k); }
    }
    parts.push(part);
  }
  return parts;
}

/**
 * The core card whose removal splits the core into the most parts (at least `HUB_PARTS`, none holding more than 60 %
 * of the rest), or −1.
 */
function sharedHub(c: Context, stressCards: number[]): number {
  const {p, d} = c;
  const inCore = new Set(d.core);
  if (d.core.length < 2 * HUB_MIN_DEGREE) return -1;
  let best = -1, bestParts = 0, bestLargest = Infinity;
  for (const hub of d.core) {
    if (p.fixed[hub]) continue;
    const coreDegree = p.neighbors[hub].filter(k => inCore.has(k)).length;
    if (coreDegree < HUB_MIN_DEGREE) continue;
    const parts = partsWithout(p, stressCards, hub).filter(part => part.some(card => inCore.has(card)));
    if (parts.length < HUB_PARTS) continue;
    const largest = Math.max(...parts.map(part => part.length));
    if (largest > 0.6 * (stressCards.length - 1)) continue;
    if (parts.length > bestParts || (parts.length === bestParts && largest < bestLargest)) { best = hub; bestParts = parts.length; bestLargest = largest; }
  }
  return best;
}

/** Mirrors a part's layout (computed with the hub on its left or above) to stand on `side` of the hub. */
function partShape(layout: Layout, p: Prepared, side: Side): UnitShape {
  const flipX = side === 2, flipY = side === 3;
  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  const points: Array<[number, number, number]> = [];
  for (const [card, at] of layout) {
    const x = flipX ? -at.x : at.x, y = flipY ? -at.y : at.y;
    points.push([card, x, y]);
    minX = Math.min(minX, x - p.width[card] / 2); maxX = Math.max(maxX, x + p.width[card] / 2);
    minY = Math.min(minY, y - p.height[card] / 2); maxY = Math.max(maxY, y + p.height[card] / 2);
  }
  // Reference: the middle of the side that faces the hub.
  const rx = side === 0 ? minX : side === 2 ? maxX : (minX + maxX) / 2;
  const ry = side === 1 ? minY : side === 3 ? maxY : (minY + maxY) / 2;
  const offsets = new Map<number, Point>([[-1, {x: 0, y: 0}]]);
  for (const [card, x, y] of points) offsets.set(card, {x: x - rx, y: y - ry});
  return {extents: {left: rx - minX, right: maxX - rx, top: ry - minY, bottom: maxY - ry}, offsets};
}

/**
 * The hub at (0, 0) with its parts and its own pendant units around it, like the branches of a radial tree: each unit
 * gets a sector of the circle in proportion to its size, is turned so the side that holds its hub-linked cards faces
 * the hub, and stands at the smallest distance along its sector's middle (in an ellipse stretched to the viewport)
 * where its cards keep their clearance from the cards placed before.
 */
function layoutAroundHub(c: Context, stressCards: number[], hub: number): Layout {
  const {p, d, shape, options} = c;
  const inCore = new Set(d.core);
  const parts = partsWithout(p, stressCards, hub);
  const multi = parts.filter(part => part.some(card => inCore.has(card))).sort((a, b) => b.length - a.length || a[0] - b[0]);
  const variants = multi.map(part => ({x: layoutGroup(c, part, {card: hub, axis: 'x'}), y: layoutGroup(c, part, {card: hub, axis: 'y'})}));
  const units: UnitShape[][] = [
    ...multi.map((_, i) => ([0, 1, 2, 3] as Side[]).map(side => partShape(side % 2 === 0 ? variants[i].x : variants[i].y, p, side))),
    ...d.children[hub].map(child => ([0, 1, 2, 3] as Side[]).map(side => shape(child, side))),
  ];
  const weights = units.map(shapes => {
    const e = shapes[0].extents;
    return Math.sqrt((e.left + e.right + gap.nodeGapX) * (e.top + e.bottom + gap.nodeGapY));
  });
  const total = weights.reduce((sum, w) => sum + w, 0);
  const result: Layout = new Map([[hub, {x: 0, y: 0}]]);
  const boxes: Extents[] = [{left: -p.width[hub] / 2, right: p.width[hub] / 2, top: -p.height[hub] / 2, bottom: p.height[hub] / 2}];
  const stretch = Math.sqrt(Math.max(0.5, Math.min(3, options.aspectRatio ?? 1.6)));
  const clearX = gap.nodeGapX, clearY = gap.nodeGapY;
  const touches = (a: Extents, b: Extents) => a.left < b.right + clearX && b.left < a.right + clearX && a.top < b.bottom + clearY && b.top < a.bottom + clearY;
  let angle = -Math.PI / 2;
  units.forEach((shapes, k) => {
    const span = 2 * Math.PI * weights[k] / total, middle = angle + span / 2;
    angle += span;
    const ux = Math.cos(middle), uy = Math.sin(middle);
    const side: Side = Math.abs(ux) * stretch >= Math.abs(uy) / stretch ? (ux >= 0 ? 0 : 2) : (uy >= 0 ? 1 : 3);
    const unitShape = shapes[side];
    const cards = [...unitShape.offsets].filter(([card]) => card >= 0);
    for (let r = ARROW_LENGTH; ; r += 16) {
      const x = ux * r * stretch, y = uy * r / stretch;
      const placedBoxes = cards.map(([card, o]) => ({left: x + o.x - p.width[card] / 2, right: x + o.x + p.width[card] / 2,
        top: y + o.y - p.height[card] / 2, bottom: y + o.y + p.height[card] / 2}));
      if (r < 60000 && placedBoxes.some(box => boxes.some(other => touches(box, other)))) continue;
      cards.forEach(([card, o], i) => { result.set(card, {x: x + o.x, y: y + o.y}); boxes.push(placedBoxes[i]); });
      break;
    }
  });
  return result;
}

/** Lays out one component; writes centres into `placed`. */
/** Decompositions of several components as one (their cards are disjoint). */
function mergeDecompositions(n: number, parts: Decomposition[]): Decomposition {
  const parent = new Int32Array(n).fill(-1), children: number[][] = Array.from({length: n}, () => []), core: number[] = [];
  for (const part of parts) {
    core.push(...part.core);
    part.parent.forEach((value, card) => { if (value >= 0) parent[card] = value; });
    part.children.forEach((list, card) => { if (list.length) children[card] = list; });
  }
  return {core, parent, children, tree: false};
}

/**
 * Lays out the cards of `members` (one component, or, when extending a drawing, every component together so that a
 * growing fan pushes unrelated cards aside); writes centres into `placed`.
 */
function layoutComponent(p: Prepared, members: number[][], placed: {x: Float64Array; y: Float64Array}, options: LayoutOptions, spacing: FanSpacing,
  keep?: Pick<Context, 'keep' | 'placed'>) {
  // Cards that may not move stay in the core, out of the fans drawn anew. Extending a drawing, the fans they would
  // belong to are found without them (`Context.ring`), and those fans are held (`holdFan`).
  const merge = (parts: Decomposition[]) => (parts.length === 1 ? parts[0] : mergeDecompositions(p.neighbors.length, parts));
  const d = merge(members.map(component => decomposeComponent(p.neighbors, component, card => Boolean(p.fixed[card]))));
  const ring = keep ? merge(members.map(component => decomposeComponent(p.neighbors, component))).children : undefined;
  for (const list of d.children) {
    if (list.length < 2) continue;
    const parent = d.parent[list[0]];
    const keys = new Map(list.map(child => [child, p.order(parent, child)]));
    list.sort((a, b) => (keys.get(a)! < keys.get(b)! ? -1 : keys.get(a)! > keys.get(b)! ? 1 : 0));
  }
  const shape = unitShapes(d.children, card => ({width: p.width[card], height: p.height[card]}), spacing);
  // Stress cards: the core, and pendant cards whose parent is a stress card with too few children to fan.
  const fanned = new Set<number>(), stressCards: number[] = [];
  const frontier = [...d.core];
  for (let read = 0; read < frontier.length; read++) {
    const card = frontier[read];
    stressCards.push(card);
    if (d.children[card].length >= FAN_MIN) fanned.add(card);
    else frontier.push(...d.children[card]);
  }
  const c: Context = {p, d, shape, fanned, options, spacing, ...keep, ring};
  const hub = p.fixed.some(Boolean) || keep?.keep ? -1 : sharedHub(c, stressCards);
  const layout = hub >= 0 ? layoutAroundHub(c, stressCards, hub) : layoutGroup(c, stressCards);
  for (const [card, at] of layout) { placed.x[card] = at.x; placed.y[card] = at.y; }
}

/**
 * Tidy: a local, minimal repair of the drawing as it is. Cards keep their clearance (exact separation), then only cards
 * that overlap or sit on a link they are not part of move, to the nearest place that clears them; a drawing without
 * such conflicts stays exactly where it is, and pinned cards never move.
 */
export function refineOrganicLayout(graph: Graph, options: LayoutOptions = {}): LayoutResult {
  const p = prepare(graph, options);
  const positions = new Map<string, PointerPosition>(graph.nodes.map(node => [node.id, {x: node.x ?? 0, y: node.y ?? 0}]));
  separateLayoutRectangles(graph, positions, {...options, repairOnly: true});
  const links: number[] = [];
  p.neighbors.forEach((list, a) => list.forEach(b => { if (a < b) links.push(a, b); }));
  const half = (size: Float64Array) => Float64Array.from(size, value => value / 2);
  const problem: StressProblem = {left: half(p.width), right: half(p.width), top: half(p.height), bottom: half(p.height),
    x: Float64Array.from(graph.nodes, node => positions.get(node.id)!.x), y: Float64Array.from(graph.nodes, node => positions.get(node.id)!.y),
    links: Int32Array.from(links), fixed: p.fixed};
  if (graph.nodes.length <= UNTANGLE_LIMIT) untangle(problem, 3, {crossings: 0, moveCost: 1 / 4});
  graph.nodes.forEach((node, i) => positions.set(node.id, {x: problem.x[i], y: problem.y[i]}));
  separateLayoutRectangles(graph, positions, {...options, repairOnly: true});
  return {positions, bends: new Map()};
}

export function computeOrganicLayout(graph: Graph, options: LayoutOptions = {}): LayoutResult {
  const p = prepare(graph, options);
  const n = graph.nodes.length;
  const placed = {x: new Float64Array(n), y: new Float64Array(n)};
  const spacing: FanSpacing = {edgeLength: ARROW_LENGTH, clearX: gap.nodeGapX, clearY: gap.nodeGapY, aspectRatio: options.aspectRatio ?? 1.6};
  const components = componentsOf(p.neighbors);
  const extending = Boolean(options.incremental || options.refine);
  const isNew = options.newNodeIds;
  const keep = extending ? {
    // Tidying holds every card firmly; extending lets the cards near the new ones give way.
    keep: (card: number) => (options.refine ? 3 : 0.8),
    placed: (card: number) => !isNew?.has(graph.nodes[card].id) && graph.nodes[card].x !== undefined && graph.nodes[card].y !== undefined,
  } : undefined;
  if (keep) layoutComponent(p, components, placed, options, spacing, keep);
  else for (const members of components) layoutComponent(p, [members], placed, options, spacing);
  const pinned = (members: number[]) => members.some(i => p.fixed[i]);
  const free = extending ? [] : components.filter(members => !pinned(members));
  if (free.length > 1 || (free.length && free.length < components.length)) {
    const items = free.map(members => ({
      boxes: members.map(i => ({minX: placed.x[i] - p.width[i] / 2, maxX: placed.x[i] + p.width[i] / 2, minY: placed.y[i] - p.height[i] / 2, maxY: placed.y[i] + p.height[i] / 2})),
      segments: members.flatMap(i => p.neighbors[i].filter(k => k > i).map(k => [placed.x[i], placed.y[i], placed.x[k], placed.y[k]] as [number, number, number, number])),
    }));
    const offsets = packComponents(items, options.aspectRatio ?? 1.6, Math.max(gap.nodeGapX, gap.nodeGapY));
    free.forEach((members, k) => { for (const i of members) { placed.x[i] += offsets[k].x; placed.y[i] += offsets[k].y; } });
    if (free.length < components.length) {
      // Free components go to the right of the drawing that pinned cards hold in place.
      let right = -Infinity, top = Infinity, left = Infinity;
      components.filter(pinned).forEach(members => members.forEach(i => { right = Math.max(right, placed.x[i] + p.width[i] / 2); top = Math.min(top, placed.y[i] - p.height[i] / 2); }));
      free.forEach(members => members.forEach(i => { left = Math.min(left, placed.x[i] - p.width[i] / 2); }));
      let freeTop = Infinity;
      free.forEach(members => members.forEach(i => { freeTop = Math.min(freeTop, placed.y[i] - p.height[i] / 2); }));
      free.forEach(members => members.forEach(i => { placed.x[i] += right + gap.groupGap - left; placed.y[i] += top - freeTop; }));
    }
  }
  const positions = new Map<string, PointerPosition>();
  graph.nodes.forEach((node, i) => positions.set(node.id, p.fixed[i] ? {x: node.x ?? 0, y: node.y ?? 0} : {x: placed.x[i], y: placed.y[i]}));
  separateLayoutRectangles(graph, positions, options);
  return {positions, bends: new Map(), fanned: true};
}
